  "employETitle": "E. Die Site",
  "employEWalk": "<a href=\"/\" class=\"text-amber-300 underline\">Start</a> · <a href=\"/chat.html\" class=\"text-amber-300 underline\">Chat</a> · <a href=\"/employ.html\" class=\"text-amber-300 underline\">Einsatz</a> · <a href=\"/Launch-Ra-Thor.html\" class=\"text-amber-300 underline\">Starten</a> · <a href=\"/micro-moment.html\" class=\"text-amber-300 underline\">Momente</a> · <a href=\"/sovereign-shard.html\" class=\"text-amber-300 underline\">Scherbe</a> · <a href=\"/web-forge.html\" class=\"text-amber-300 underline\">Schmiede</a> · <a href=\"/contact.html\" class=\"text-amber-300 underline\">Kontakt</a> · <a href=\"/privacy.html\" class=\"text-amber-300 underline\">Datenschutz</a>",
  "employFBody": "AG-SML: persönlich / Forschung / bescheidene Freiberuflichkeit. Kommerziell / Organisation / Umsatz → kostenpflichtige Lizenz. Nutzen Sie das <a href=\"/contact.html#commercial-inquiry\" class=\"text-amber-300 underline\">Formular der Handelsanfrage</a> oder schreiben Sie an <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>.",
  "employFTitle": "F. Lizenz",
  "employGBody": "No measured METR-Zahlen. Keine Zertifikatsanmeldung. Das Arbeitspaket ist ein <strong class=\"text-amber-300\">DRAFT</strong>.",
  "employGTitle": "G. Ehrliche Lücken",
  "employLoop1": "<strong class=\"text-amber-300\">Absicht</strong> — einen Entwurf, einen Plan, eine Prüfung oder eine Ablehnung verlangen.",
  "employLoop2": "<strong class=\"text-amber-300\">Tore bestehen</strong> — TOLC 8 ist der stehende Test.",
  "employLoop3": "<strong class=\"text-amber-300\">Optionales Modell</strong> — auf dem Gerät bleiben, oder den Kontext in ein Modell kopieren, das Sie wählen. Eine optionale Grok-Sitzung ist kein xAI-Produkt.",
  "employLoop4": "<strong class=\"text-amber-300\">Prüfung</strong> — den Entwurf lesen. Behalten oder ablehnen.",
  "employLoop5": "<strong class=\"text-amber-300\">Handeln</strong> — die Handlung gehört Ihnen.",
  "employLoopFoot": "Vertrag zum optionalen Modell: <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/OPTIONAL_MODEL.md\" class=\"text-amber-300 underline\">docs/OPTIONAL_MODEL.md</a>. Keine zertifizierte AgentOS- oder Hermes-Einbindung.",
  "employLoopTitle": "Die Schleife",
  "employOrgBuy": "Was sie kaufen: Zeit und Rechte, einen Arbeitsablauf unter derselben Verfassung einzuhüllen. Die Zulassungshülle prüfen. Behalten oder ablehnen.",
  "employOrgHow": "Wie man anfragt: das Formular <a href=\"/contact.html#commercial-inquiry\" class=\"text-amber-300 underline\">Handelsanfrage</a> oder <a href=\"mailto:info@Rathor.ai\" class=\"text-amber-300 underline\">info@Rathor.ai</a>. Ein Mensch antwortet. Es gibt keinen sofortigen Lizenzschlüssel.",
  "employOrgNot": "Was sie nicht kaufen: ISO 42001, Konformität mit dem EU AI Act, Messwerte mit ≠ METR, eine AGSi-Gewähr, einen gehosteten Schlüssel-Proxy oder eine fertige Welt.",
  "employOrgTitle": "Organisationen",
  "employOrgWho": "Wer zahlt: organisationsweite Nutzung, umsatzbringende Nutzung, eine Produkteinbettung, ein Kundendienst oder eine Verfassung für Mitarbeitende und Agenten.",
  "employSisterBody": "Lehrplan, das menschliche Spiel und prüfbare Studien leben in eigenen GitHub-Repos — nicht als zusätzliche Produkttüren auf dieser Site. Die Karte öffnen: <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/SISTER_ADOPTION.md\" class=\"text-amber-300 underline\">docs/SISTER_ADOPTION.md</a>. Arbeit zu Fusion, High-Tc, Protein und Worldship bleibt Studium, das Sie dort prüfen.",
  "employSisterTitle": "Öffentliche Schwesterbäume",
  "employSpine": "Rückgrat: <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/docs/EMPLOY.md\" class=\"text-amber-300 underline\">docs/EMPLOY.md</a>. Öffentliche Unterrichtung: <a href=\"/briefing.html\" class=\"text-amber-300 underline\">/briefing.html</a>.",
  "employStamp": "16. September 2026 · Workspace 14.15.6 · Fähig · Begrenzt · Korrigierbar",
  "employWrap1": "<strong class=\"text-amber-300\">Kontext kopieren</strong> — <a href=\"/chat.html\" class=\"text-amber-300 underline\">Kontext kopieren</a> oder <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/wrappers/system-prompt.txt\" class=\"text-amber-300 underline\">wrappers/system-prompt.txt</a>.",
  "employWrap2": "<strong class=\"text-amber-300\">Fertigkeit</strong> — <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/skills/ra-thor-employ/SKILL.md\" class=\"text-amber-300 underline\">skills/ra-thor-employ/SKILL.md</a>.",
  "employWrap3": "<strong class=\"text-amber-300\">Lokale HTTP-Einhüllung</strong> — <a href=\"https://github.com/Eternally-Thriving-Grandmasterism/Ra-Thor/blob/main/wrappers/local-shim/rathor_wrap.py\" class=\"text-amber-300 underline\">wrappers/local-shim/rathor_wrap.py</a>.",
  "employWrap4": "<strong class=\"text-amber-300\">Lattice Chat, lokales Backend</strong> — <a href=\"/chat.html\" class=\"text-amber-300 underline\">/chat.html</a> → <code class=\"text-amber-200\">http://localhost:11434/v1</code>.",
